 qa=[dict(t='e', q='为什么上帝会用这么多不同的文体（诗歌、历史、书信、预言）来写圣经，而不是写成一本整齐的教义手册？', a=['因为人不只是用头脑认识上帝，也用心、用情感、用想象、用记忆去认识。历史让我们看见上帝在真实时空中的作为；诗歌让我们学会向上帝倾心吐意；书信回应具体教会的问题；预言打开未来的视野。', '这种多样性也说明，上帝的话能进入每一种人生处境：喜乐时有赞美诗，哀伤时有哀歌，迷惑时有智慧书，失望时有应许。'], my=True)],
